theorem ucb_index_excludes_suboptimal {muHat : Fin K → ℝ} {c : Fin K → ℝ}
    {mu : Fin K → ℝ} {i star : Fin K}
    (hi : |muHat i - mu i| ≤ c i) (hstar : |muHat star - mu star| ≤ c star)
    (hgap : 2 * c i + 2 * c star < mu star - mu i) :
    ucbIndex muHat c i < ucbIndex muHat c star

theorem ucb_not_argmax_suboptimal {muHat : Fin K → ℝ} {c : Fin K → ℝ}
    {mu : Fin K → ℝ} {i star : Fin K}
    (hi : |muHat i - mu i| ≤ c i) (hstar : |muHat star - mu star| ≤ c star)
    (hgap : 2 * c i + 2 * c star < mu star - mu i) :
    ¬ (∀ j : Fin K, ucbIndex muHat c j ≤ ucbIndex muHat c i)

theorem expected_regret_decomposition {g : Fin K → ℝ} {N : Fin K → ℕ}
    {r : Fin K → ℝ}
    (hgood : ∀ i : Fin K, g i * (N i : ℝ) ≤ r i) :
    regret g N ≤ ∑ i : Fin K, r i

theorem bayesUpdate_normalized {prior lik : Fin n → ℝ}
    (hZ : marginalLikelihood prior lik ≠ 0) :
    ∑ θ, bayesUpdate prior lik θ = 1

lemma bayesUpdate_proportional {prior lik : Fin n → ℝ}
    (hZ : marginalLikelihood prior lik ≠ 0) (θ : Fin n) :
    bayesUpdate prior lik θ * marginalLikelihood prior lik = prior θ * lik θ

theorem posterior_mean_minimizes_squared_risk {post : Fin n → ℝ}
    (hpost : ProbVec post) (θhat : ℝ) :
    squaredRisk post (posteriorMean post) ≤ squaredRisk post θhat

theorem solIter_succ_stable (M : FinSCM n) (topo : Fin n ≃ Fin n) {k m : ℕ}
    (hk : k < n) (hm : m < n) (hlt : m < k) :
    solIter M topo (k + 1) (topo ⟨m, hm⟩) = solIter M topo k (topo ⟨m, hm⟩)
